 1	import { query, update } from '../db.js';
 2	
 3	// The repository pattern the project is migrating toward: promise-based,
 4	// one place per table, no query construction anywhere else.
 5	export class UserRepository {
 6	  findActive() {
 7	    return new Promise((resolve, reject) => {
 8	      query('users', (u) => u.deleted_at === null, (err, rows) =>
 9	        err ? reject(err) : resolve(rows));
10	    });
11	  }
12	
13	  findById(id) {
14	    return new Promise((resolve, reject) => {
15	      query('users', (u) => u.id === id, (err, rows) =>
16	        err ? reject(err) : resolve(rows[0] ?? null));
17	    });
18	  }
19	
20	  softDelete(id, when) {
21	    return new Promise((resolve, reject) => {
22	      update('users', id, { deleted_at: when }, (err, row) =>
23	        err ? reject(err) : resolve(row));
24	    });
25	  }
26	}
27	// A deliberately tiny in-memory database with a callback API.
28	// The callback style is the point: Chapter 5 migrates the service layer off it.
29	
30	const tables = {
31	  users: [
32	    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
33	    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
34	    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
35	  ],
36	  orders: [
37	    { id: 10, user_id: 1, total_cents: 4200, status: 'paid', deleted_at: null },
38	    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
39	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
40	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
41	  ],
42	  payments: [
43	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
44	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
45	  ],
46	};
47	
48	export function reset() {
49	  tables.users[2].deleted_at = '2026-01-04';
50	  tables.orders.forEach((o) => { o.deleted_at = null; });
51	}
52	
53	// Old-style callback query. Accepts a table name and a predicate.
54	export function query(table, predicate, callback) {
55	  setImmediate(() => {
56	    const rows = tables[table];
57	    if (!rows) return callback(new Error(`no such table: ${table}`));
58	    try {
59	      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
60	    } catch (err) {
61	      callback(err);
62	    }
63	  });
64	}
65	
66	export function update(table, id, patch, callback) {
67	  setImmediate(() => {
68	    const row = (tables[table] || []).find((r) => r.id === id);
69	    if (!row) return callback(new Error(`no row ${id} in ${table}`));
70	    Object.assign(row, patch);
71	    callback(null, { ...row });
72	  });
73	}

